package mx.elmuelle.pdv;
import android.content.*;import android.database.Cursor;import android.graphics.BitmapFactory;import android.security.keystore.*;import android.util.Base64;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
import net.zetetic.database.sqlcipher.SQLiteDatabase;
public final class NativeRuntime {
 static volatile String startupFailure;
 static volatile PeripheralHub peripherals;private static volatile boolean peripheralForeground;
 static Context context;static UsbScaleHost scales;static PrinterHost printers;static final Map<Integer,SQLiteDatabase> databases=new HashMap<>();static int nextDatabase=1;private static boolean initialized=false;
 public static native int start(String script,String root,String library,String cache,String token,int port);
 static synchronized void initialize(Context value){if(initialized)return;context=value.getApplicationContext();System.loadLibrary("sqlcipher");System.loadLibrary("node");System.loadLibrary("muelle");scales=new UsbScaleHost(context);printers=new PrinterHost(context);peripherals=new PeripheralHub(context,printers,scales);peripherals.foreground(peripheralForeground);initialized=true;}
 static void peripheralForeground(boolean value){peripheralForeground=value;PeripheralHub hub=peripherals;if(hub!=null)hub.foreground(value);}
 static javax.crypto.SecretKey key()throws Exception {KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("muelle-storage-v1")){KeyGenerator generator=KeyGenerator.getInstance("AES","AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("muelle-storage-v1",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (javax.crypto.SecretKey)store.getKey("muelle-storage-v1",null);}
 static String seal(String text)throws Exception {Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());return "ak1:"+Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(text.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);}
 static String unseal(String text)throws Exception {String[] parts=text.split(":");if(parts.length!=3||!parts[0].equals("ak1"))throw new SecurityException();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[1],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(parts[2],Base64.NO_WRAP)),StandardCharsets.UTF_8);}
 static File privatePath(String value)throws Exception {File file=new File(value).getCanonicalFile(),root=context.getNoBackupFilesDir().getCanonicalFile(),cache=context.getCacheDir().getCanonicalFile();String name=file.getPath();if(!name.startsWith(root.getPath()+"/")&&!name.startsWith(cache.getPath()+"/"))throw new SecurityException();return file;}
 static Object[] arguments(JSONArray values)throws Exception {Object[] args=new Object[values.length()];for(int i=0;i<args.length;i++)args[i]=values.isNull(i)?null:values.get(i);return args;}
 static JSONArray rows(Cursor cursor)throws Exception {JSONArray out=new JSONArray();try{while(cursor.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<cursor.getColumnCount();i++){Object v;switch(cursor.getType(i)){case Cursor.FIELD_TYPE_NULL:v=JSONObject.NULL;break;case Cursor.FIELD_TYPE_INTEGER:v=cursor.getLong(i);break;case Cursor.FIELD_TYPE_FLOAT:v=cursor.getDouble(i);break;case Cursor.FIELD_TYPE_BLOB:throw new SecurityException("No se exportan BLOB por este puente");default:v=cursor.getString(i);}row.put(cursor.getColumnName(i),v);}out.put(row);}}finally{cursor.close();}return out;}
 public static byte[] commandUtf8(byte[] input){return command(new String(input,StandardCharsets.UTF_8)).getBytes(StandardCharsets.UTF_8);}
 public static synchronized String command(String input){String operation="";try{
  JSONObject args=new JSONObject(input);operation=args.getString("op");Object result=JSONObject.NULL;
  switch(operation){
   case "appVersion":result=new JSONObject().put("versionCode",BuildConfig.VERSION_CODE).put("versionName",BuildConfig.VERSION_NAME);break;
   case "startupFailure":{String code=args.optString("code","STARTUP_ERROR");startupFailure=code.matches("[A-Za-z0-9_]{1,60}")?code:"STARTUP_ERROR";result=true;break;}
   case "seal":result=seal(args.getString("text"));break;case "unseal":result=unseal(args.getString("text"));break;
   case "dbOpen":{File file=privatePath(args.getString("path"));String password=args.getString("key");if(!password.matches("[a-f0-9]{64}"))throw new SecurityException();boolean readOnly=args.optBoolean("readOnly");SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getPath(),password,null,readOnly?SQLiteDatabase.OPEN_READONLY:SQLiteDatabase.OPEN_READWRITE|SQLiteDatabase.CREATE_IF_NECESSARY,null);int id=nextDatabase++;databases.put(id,db);result=id;break;}
   case "dbClose":{SQLiteDatabase db=databases.remove(args.getInt("id"));if(db!=null)db.close();break;}
   case "dbExec":{SQLiteDatabase db=databases.get(args.getInt("id"));for(String sql:args.getString("sql").split(";(?=(?:[^']*'[^']*')*[^']*$)")){sql=sql.trim();if(sql.isEmpty())continue;if(sql.toUpperCase(Locale.ROOT).startsWith("PRAGMA")){try(Cursor c=db.rawQuery(sql,new String[0])){while(c.moveToNext()){};}}else db.execSQL(sql);}break;}
   case "dbQuery":{SQLiteDatabase db=databases.get(args.getInt("id"));Object[] params=arguments(args.getJSONArray("args"));if(args.getString("mode").equals("run")){db.execSQL(args.getString("sql"),params);JSONObject row=rows(db.rawQuery("SELECT changes() AS changes,last_insert_rowid() AS lastInsertRowid",new String[0])).getJSONObject(0);result=row;}else result=rows(db.rawQuery(args.getString("sql"),params));break;}
   case "dbSnapshot":{SQLiteDatabase db=databases.get(args.getInt("id"));String output=privatePath(args.getString("path")).getPath();if(new File(output).exists())throw new SecurityException();db.execSQL("ATTACH DATABASE ? AS muelle_snapshot KEY ?",new Object[]{output,args.getString("key")});try{try(Cursor c=db.rawQuery("SELECT sqlcipher_export('muelle_snapshot')",new String[0])){while(c.moveToNext()){};}}finally{db.execSQL("DETACH DATABASE muelle_snapshot");}break;}
   case "image":{byte[] bytes=Base64.decode(args.getString("data"),Base64.NO_WRAP);if(bytes.length>5242880)throw new SecurityException();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=0||options.outHeight<=0||options.outWidth>8192||options.outHeight>8192||(long)options.outWidth*options.outHeight>32000000)throw new SecurityException();android.graphics.Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null)throw new SecurityException();bitmap.recycle();result=true;break;}
   case "scaleList":result=scales.devices();break;case "scaleState":result=scales.state();break;case "scaleOpen":result=scales.open(args.getJSONObject("profile"));break;case "scaleClose":scales.close();break;case "scaleDiagnostics":result=scales.diagnostics();break;case "scaleTraceStart":result=scales.startTrace();break;case "scaleTraceStop":result=scales.stopTrace();break;
   case "printerList":result=printers.devices();break;case "printerConfigure":result=printers.configure(args.getJSONObject("profile"));break;case "printerStatus":result=printers.status();break;case "printerTestConnection":result=printers.testConnection();break;case "printerPrint":result=printers.print(args.getString("data"));break;
   case "peripheralStatus":result=peripherals.state();break;case "peripheralDiscover":result=peripherals.discover();break;case "peripheralConnect":result=peripherals.connect(args.getString("id"));break;case "peripheralReconnect":result=peripherals.reconnect();break;case "peripheralAutomatic":result=peripherals.automatic(args.getBoolean("enabled"));break;
   default:throw new SecurityException();
  }
  return new JSONObject().put("ok",true).put("value",result).toString();
 }catch(Exception error){try{return new JSONObject().put("ok",false).put("error","Operación nativa rechazada: "+operation+(operation.startsWith("printer")?" · "+String.valueOf(error.getMessage()).replaceAll("[\\r\\n]"," ").substring(0,Math.min(180,String.valueOf(error.getMessage()).length())):"")+(operation.startsWith("scale")?" · "+(error.getMessage()!=null&&error.getMessage().matches("[A-Z0-9_]{3,60}")?error.getMessage():"SCALE_OPERATION_FAILED"):"")+" ("+error.getClass().getSimpleName()+")").toString();}catch(Exception impossible){return "{\"ok\":false}";}}
 }
}
